7	use Guard\Config\ConfigurationLoader;
8	use Guard\Diagnostic\PolicyException;
9	use Guard\Execution\Pipeline;
10	use Guard\Execution\Registry;
11	use Guard\Reporting\Baseline;
12	use Guard\Reporting\Filtering\FindingFilter;
13	use Guard\Reporting\Filtering\ReportScope;
14	use Guard\Reporting\Reporter;
15	use JsonException;
16	use Nette\Neon\Exception as NeonException;
17	use RuntimeException;
18	use Symfony\Component\Console\Input\InputInterface;
19	use Symfony\Component\Console\Output\OutputInterface;
20	
21	/**
22	 * Checks every policy, consumes the baseline, and applies display-only diagnostic filters.
23	 */
24	final class CheckRun
25	{
26	    /**
27	     * Allows callers to supply additional policies.
28	     */
29	    public function __construct(private ?Registry $registry = null)
30	    {
31	    }
32	
33	    /**
34	     * @throws RuntimeException
35	     * @throws JsonException
36	     * @throws NeonException
37	     */
38	    public function run(string $path, string $format, InputInterface $input, OutputInterface $output): int
39	    {
40	        $query = $input->getOption('query');
41	        if ($query !== null && (!is_string($query) || trim($query) === '')) {
42	            throw new PolicyException('Provide non-empty search text for --query, such as --query=metrics.');
43	        }
44	        $level = $input->getOption('level');
45	        $filter = new FindingFilter($query ?? '', is_string($level) ? $level : null, $input->getOption('fixable') === true);
46	        $baseline = $this->baselinePath($path, $input);
47	        $file = new BaselineFile();
48	        $json = $baseline === null ? null : $file->read($baseline);
49	        if ($json !== null) {
50	            $file->validate($json, $baseline);
51	        }
52	        $configuration = (new ConfigurationLoader())->load($path);
53	        $plan = (new Pipeline($this->registry))->run($configuration, $path, false);
54	        $match = $json === null ? null : (new Baseline())->filter($plan->findings, $json);
55	        $findings = $match === null ? $plan->findings : $match->findings;
56	        $visible = $filter->select($findings);
57	        $scope = $baseline === null && count($visible) === count($findings) ? null : new ReportScope($findings, $baseline, $match === null ? 0 : $match->suppressed, $match === null ? 0 : $match->unmatched);
58	        $reporter = new Reporter();
59	        $output->write($reporter->render($visible, [], $format, 'checked', $output->isDecorated(), $scope), false, OutputInterface::OUTPUT_RAW);
60	        return $reporter->hasErrors($findings) ? 1 : 0;
61	    }
62	
63	    /**
64	     * Uses the conventional file if present, but never ignores an explicitly missing baseline.
65	     * @throws PolicyException
66	     */
67	    public function baselinePath(string $config, InputInterface $input): ?string
68	    {
69	        $requested = $input->getOption('baseline');
70	        if ($input->getOption('no-baseline') === true) {
71	            if ($requested !== null) {
72	                throw new PolicyException('Use either --baseline or --no-baseline, not both.');
73	            }
74	            return null;
75	        }
76	        $path = (new BaselineFile())->path($config, is_string($requested) ? $requested : null);
77	        return $requested !== null || file_exists($path) || is_link($path) ? $path : null;
78	    }
79	}
