    "$id": "https://k-kinzal.github.io/php-ai-toolkit/decisions-lint/rules.schema.json",
    "title": "decisions-lint rule file",
    "description": "A set of nuanced rules that decisions.yaml imports. Each rule names the declarations it judges, the question it asks the decision model, and which answers violate it.",
    "type": "object",
    "additionalProperties": false,
    "required": ["version", "rules"],
    "properties": {
        "version": {
            "const": 1,
            "description": "The rule file format version; always 1."
        },
        "rules": {
            "$ref": "#/$defs/ruleSet",
            "description": "The rules of this file, keyed by rule id."
        }
    },
    "$defs": {
        "ruleId": {
            "type": "string",
            "pattern": "^[a-z0-9]+([.-][a-z0-9]+)*$",
            "description": "a rule id made of lower-case letters, digits, dots and hyphens, such as cohesion.method-belongs-to-class"
        },
        "ruleSet": {
            "type": "object",
            "propertyNames": {
                "$ref": "#/$defs/ruleId"
            },
            "additionalProperties": {
                "$ref": "#/$defs/rule"
            }
        },
        "rule": {
            "allOf": [
                {
                    "$ref": "#/$defs/ruleFields"
                },
                {
                    "required": ["target", "decision", "violations"]
                }
            ]
        },
        "ruleFields": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "description": {
                    "type": "string",
                    "description": "What the rule protects, shown by the rules command."
                },
                "severity": {
                    "enum": ["error", "warning", "info"],
                    "description": "How a violation is reported; error fails the check by default."
                },
                "enabled": {
                    "type": "boolean",
                    "description": "Whether the rule runs; set false in decisions.yaml to switch off an imported rule."
                },
                "paths": {
                    "type": "array",
                    "items": {
                        "type": "string",
                        "minLength": 1
                    },
                    "description": "File globs relative to decisions.yaml the rule applies to; omit to apply to every configured path."
                },
                "exclude": {
                    "type": "array",
                    "items": {
                        "type": "string",
                        "minLength": 1
                    },
                    "description": "File globs relative to decisions.yaml the rule skips."
                },
                "target": {
                    "$ref": "#/$defs/target"
                },
                "context": {
                    "enum": ["declaration", "class", "file"],
                    "description": "How much source the model reads with the target: the declaration alone, its whole class, or its whole file."
                },
                "decision": {
                    "$ref": "#/$defs/decision"
                },
                "violations": {
                    "type": "array",
                    "minItems": 1,
                    "items": {
                        "$ref": "#/$defs/violation"
                    },
                    "description": "The answers that violate the rule, each with the message and the fix to report."
                }
            }
        },
        "target": {
            "type": "object",
            "additionalProperties": false,
            "required": ["kind"],
            "description": "Which declarations of a matching file the rule judges.",
            "properties": {
                "kind": {
                    "enum": ["file", "class", "interface", "trait", "enum", "method", "function", "property"],
                    "description": "The kind of declaration to judge; file judges the whole file once."
                },
                "visibility": {
                    "type": "array",
                    "items": {
                        "enum": ["public", "protected", "private"]
                    },
                    "description": "Keep only methods or properties with one of these visibilities."
                },
                "names": {
                    "type": "array",
                    "items": {
                        "type": "string",
                        "minLength": 1
                    },
                    "description": "Keep only declarations whose short name matches one of these globs."
                },
                "exclude_names": {
                    "type": "array",
                    "items": {
                        "type": "string",
                        "minLength": 1
                    },
                    "description": "Drop declarations whose short name matches one of these globs, such as __*."
                },
                "static": {
                    "type": "boolean",
                    "description": "Keep only static (true) or only non-static (false) declarations."
                }
            }
        },
        "decision": {
            "type": "object",
            "additionalProperties": false,
            "description": "The question the model answers about each target.",
            "properties": {
                "type": {
                    "enum": ["predicate", "choice", "score"],
                    "description": "predicate asks whether a statement holds, choice picks one option, score places the target on a scale."
                },
                "instructions": {
                    "type": "string",
                    "minLength": 1,
                    "description": "The question, with {name}, {class}, {signature} and other placeholders filled from the target."
                },
                "choices": {
                    "type": "object",
                    "propertyNames": {
                        "type": "string",
                        "pattern": "^[A-Za-z0-9_-]+$",
                        "description": "an option name made of letters, digits, underscores and hyphens"
                    },
                    "additionalProperties": {
                        "type": "string"
                    },
                    "description": "For a choice: option name to description."
                },
                "levels": {
                    "type": "array",
                    "minItems": 2,
                    "maxItems": 10,
                    "items": {
                        "type": "string",
                        "minLength": 1
                    },
                    "description": "For a score: the level descriptions from lowest (0) to highest."
                },
                "threshold": {
                    "type": "number",
                    "minimum": 0,
                    "maximum": 1,
                    "description": "The probability (predicate) or confidence (choice, score) a violation needs; 0.5 when omitted."
                }
            }
        },
        "violation": {
            "type": "object",
            "additionalProperties": false,
            "required": ["message", "fix"],
            "description": "One answer that violates the rule.",
            "properties": {
                "answer": {
                    "type": ["boolean", "string"],
                    "description": "The violating answer: true or false for a predicate, an option name for a choice."
                },
                "min_score": {
                    "type": "number",
                    "description": "For a score: the lowest violating score, inclusive."
                },
                "max_score": {
                    "type": "number",
                    "description": "For a score: the highest violating score, inclusive."
                },
                "message": {
                    "type": "string",
                    "minLength": 1,
                    "description": "What is wrong, with placeholders such as {name} and {class}."
                },
                "fix": {
                    "type": "string",
                    "minLength": 1,
                    "description": "What to change so the rule passes, with the same placeholders."
                }
            }
        }
    }
}

